def sign(x):
    if x > 0:
        return "positive"
    if x < 0:
        return "negative"
    return "zero"

print(sign(5), sign(-2), sign(0))

def divisible(n, d):
    return n % d == 0

def is_leap(year):
    return divisible(year, 4) and (not divisible(year, 100) or divisible(year, 400))

print(is_leap(2024), is_leap(1900), is_leap(2000))

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(5))
